/* Nota de paleta: el HTML aprobado usa blanco puro (#ffffff) para superficies
   de tarjeta y texto sobre azul. §1.1 del design-system no define un token de
   blanco; --bw-warm-cream (#FAF8F4) es el valor más cercano de la paleta y se
   usa en su lugar. */

.content {
  flex: 1;
  overflow-y: auto;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-input-text);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin: 0 0 16px;
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-input-text);
  outline: none;
  font-family: inherit;
  background: var(--bw-warm-cream);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.btnPrimary {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.btnPrimary:hover {
  opacity: 0.88;
}

.btnPrimary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.pagInfo {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.disabledReason {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  font-style: italic;
}

.errorAlert {
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  border-radius: 5px;
  font-size: 13px;
}

.loading {
  padding: 32px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: 14px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.noResults {
  margin-bottom: 14px;
  padding: 24px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: 14px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageButton {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: all 0.12s;
}

.pageButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageButton.active {
  background: var(--bw-input-text);
  border-color: var(--bw-input-text);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageButton.ctrl {
  color: var(--bw-input-placeholder);
}

.pageButton:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

