import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * La pasa el shell (F-118). MSG-02 no está en el alcance del MVP, así que
   * abrir un hilo no lleva a ningún sitio: se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Mensaje de error legible para las dos formas de fallo de PostgREST: un
 * `Error` de red y el objeto plano `{ code, message }` del rechazo. Sin esto,
 * `String(e)` enseña `[object Object]` y se come el `PGRST201` que explica el
 * fallo (F-020).
 */
function errorMessage(e: unknown): string {
  const base = 'No se pudieron cargar los hilos.';
  if (e instanceof Error) return `${base} ${e.message}`;
  if (e !== null && typeof e === 'object') {
    const rec = e as Record<string, unknown>;
    const code = typeof rec.code === 'string' ? rec.code : '';
    const message = typeof rec.message === 'string' ? rec.message : '';
    const detail = [code, message].filter(Boolean).join(' · ');
    if (detail) return `${base} ${detail}`;
  }
  return `${base} ${String(e)}`;
}

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es la pantalla, no un componente de presentación: lee el perfil de sesión,
 * llama a `fetchThreadPage` con `profile.orgId` y posee el estado de búsqueda
 * y de página. La lista en sí (filas, estado vacío) vive en `ThreadList`.
 */
export function Messages({ profile, now: nowProp, onOpenThread }: MessagesProps) {
  // F-118: el shell cablea esta prop desde App.tsx, pero MSG-02 no existía
  // cuando se escribió esta pantalla. Se recibe para mantener la firma pública
  // y se ignora: abrir un hilo no conduce a ninguna parte todavía.
  void onOpenThread;

  const now = nowProp ?? new Date();
  const [search, setSearch] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(errorMessage(e));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, query, page]);

  const pages = pageCount(total);

  function submitSearch(e: FormEvent) {
    e.preventDefault();
    setPage(1);
    setQuery(search.trim());
  }

  function goToPage(next: number) {
    if (next >= 1 && next <= pages) {
      setPage(next);
    }
  }

  const noResults = query !== '' && threads.length === 0;

  return (
    <div className={styles.content}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de
        extremo a extremo.
      </p>

      <div className={styles.actionsBar}>
        <form className={styles.searchWrap} onSubmit={submitSearch}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </form>

        {/* DIR-01 no está entre las 8 pantallas del alcance (Plan §9): el botón
            se pinta deshabilitado con el motivo visible, como el de subida de
            INV-01 (F-023 e). */}
        <button type="button" className={styles.btnPrimary} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.disabledReason} data-testid="directorio-scope">
          El Directorio queda fuera del MVP
        </span>

        <span className={styles.pagInfo} data-testid="pag-info">
          {total.toLocaleString('es-ES')} hilos · Página {page} de {pages}
        </span>
      </div>

      {error !== null && (
        <div className={styles.errorAlert} role="alert">
          {error}
        </div>
      )}

      {loading ? (
        <div className={styles.loading}>Cargando hilos…</div>
      ) : error !== null ? null : noResults ? (
        <p className={styles.noResults}>No se encontraron hilos para «{query}».</p>
      ) : (
        /* MSG-02 no está en el alcance: el handler no hace nada. */
        <ThreadList threads={threads} now={now} onOpen={() => { /* vacío a propósito */ }} />
      )}

      {!loading && error === null && total > 0 && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={`${styles.pageButton} ${styles.ctrl}`}
            onClick={() => goToPage(page - 1)}
            disabled={page <= 1}
            aria-label="Página anterior"
          >
            ‹
          </button>
          {Array.from({ length: pages }, (_, i) => i + 1).map((p) => (
            <button
              key={p}
              type="button"
              className={`${styles.pageButton} ${p === page ? styles.active : ''}`}
              aria-current={p === page ? 'page' : undefined}
              onClick={() => goToPage(p)}
            >
              {p}
            </button>
          ))}
          <button
            type="button"
            className={`${styles.pageButton} ${styles.ctrl}`}
            onClick={() => goToPage(page + 1)}
            disabled={page >= pages}
            aria-label="Página siguiente"
          >
            ›
          </button>
        </div>
      )}
    </div>
  );
}

