/* Nota de paleta: el HTML aprobado usa blanco puro (#ffffff) para las
   superficies de tarjeta. §1.1 del design-system no define un token de blanco;
   --bw-warm-cream (#FAF8F4) es el valor más cercano de la paleta y se usa en
   su lugar. */

.threadList {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.threadRow {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.threadRow:last-child {
  border-bottom: none;
}

.threadOpen {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: var(--bw-warm-cream);
  border: none;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-body);
  color: var(--bw-input-text);
  text-align: left;
  cursor: pointer;
  transition: background 0.12s;
}

.threadOpen:hover {
  background: var(--bw-hover-surface);
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadOrg {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-input-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.threadTs {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
  justify-self: end;
  align-self: center;
}

.threadBot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadPreview {
  font-size: 12px;
  color: var(--bw-steel-mist);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.threadFill {
  /* Celda vacía del grid: no pinta nada, solo equilibra la segunda columna. */
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Tonos de estado: el mapeo hex→token vive en el CSS, que es su sitio
   (stateTone() en app/src/lib/threads.ts devuelve el tono, no el color). */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 40px 24px;
  text-align: center;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyText {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  max-width: 420px;
}

.emptyActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.primaryButton {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.primaryButton:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.disabledReason {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  font-style: italic;
}

