import { previewLabel, relativeTime, stateTone, type ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas en el orden exacto en que las recibe —el orden es del
 * servidor: última actividad primero— y avisa con el id del hilo al intentar
 * abrirlo. No carga datos ni pagina: eso vive en `Messages`.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con
          otras organizaciones.
        </p>
        <div className={styles.emptyActions}>
          {/* DIR-01 no está entre las 8 pantallas del MVP (Plan §9): el control
              existe pero no lleva a ninguna parte. Se pinta deshabilitado con
              el motivo visible, como el botón de subida de INV-01 (F-023 e). */}
          <button type="button" className={styles.primaryButton} disabled>
            Ir al Directorio
          </button>
          <span className={styles.disabledReason}>El Directorio queda fuera del MVP</span>
        </div>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          <li key={thread.id} className={styles.threadRow}>
            {/* El botón va DENTRO del <li>: el <li> conserva su rol listitem
                implícito y el botón lleva el nombre accesible del hilo (F-131).
                Un role="button" sobre el li lo convertiría en un segundo botón
                con el mismo nombre accesible y rompería el contrato. */}
            <button
              type="button"
              className={styles.threadOpen}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.threadTop}>
                <span className={styles.threadOrg}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry !== '' && (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                )}
              </span>
              <span className={styles.threadTs}>
                {relativeTime(thread.lastItemAt, now)}
              </span>
              <span className={styles.threadBot}>
                <span className={styles.threadPreview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.stateBadge} ${styles[tone]}`}>
                  {thread.state}
                </span>
              </span>
              {/* Cuarta celda del grid 2×2 del HTML aprobado: vacía. */}
              <span className={styles.threadFill} />
            </button>
          </li>
        );
      })}
    </ul>
  );
}
